// Des: Send a file or image: only from the outbox folder, size and type checked, file chooser intercepted, upload verified once
// Flo: check path (inside outbox, size, type, hash) > halt+pace gate > open chat > send row key = file hash > attach click > chooser event > set files > wait until uploaded
// I/O: Sess + chat + file path (caller) > Out (sent, dup, dry); message with the file name in the chat
// ===================================================================
const std = @import("std"); const sess = @import("ru-sess-ctxz.zig"); const opn = @import("ru-chat-open.zig"); const cdp = @import("nt-cdpz-sock.zig"); const snap = @import("ru-page-snap.zig"); const file = @import("st-stor-file.zig"); const extr = @import("ru-page-extr.zig"); const fnd = @import("ru-labl-find.zig"); const priv = @import("ru-safe-priv.zig");
const CF = .{ .calz = 15000, .evwt = 5000, .exts = @as([]const []const u8, &.{ "png", "jpg", "jpeg", "gif", "webp", "mp4", "mov", "pdf", "txt", "doc", "docx", "xls", "xlsx", "ppt", "pptx", "zip" }) };
pub const Out = enum { sent, dup, dry };
pub const Checked = struct { path: []const u8, name: []const u8, size: u64, hash: [64]u8 };
pub fn extOk(name: []const u8) bool { const dot = std.mem.lastIndexOfScalar(u8, name, '.') orelse return false; const ext = name[dot + 1 ..]; for (CF.exts) |okx| { if (std.ascii.eqlIgnoreCase(okx, ext)) return true; } return false; }
pub fn check(aren: std.mem.Allocator, iozz: std.Io, outbox: []const u8, raw: []const u8, maxz: u64) !Checked { if (outbox.len == 0 or raw.len == 0) return error.BadJob; const root = try std.fs.path.resolve(aren, &.{outbox}); const full = try std.fs.path.resolve(aren, &.{ root, raw }); if (!std.mem.startsWith(u8, full, root) or full.len <= root.len or !std.fs.path.isSep(full[root.len])) return error.BadJob; const name = std.fs.path.basename(full); if (!extOk(name)) return error.BadJob; const body = file.fileRead(aren, iozz, full, @intCast(maxz)) catch |err| { if (err == error.StreamTooLong) return error.TooBig; return error.NoElem; }; var dig: [32]u8 = undefined; std.crypto.hash.sha2.Sha256.hash(body, &dig, .{}); return .{ .path = full, .name = name, .size = body.len, .hash = std.fmt.bytesToHex(dig, .lower) }; }
fn chooseFiles(ses: *sess.Sess, abs: []const u8) !void { _ = try ses.conn.callJson(ses.aren, "Page.enable", "", CF.calz); _ = try ses.conn.callJson(ses.aren, "Page.setInterceptFileChooserDialog", "{\"enabled\":true}", CF.calz); defer _ = ses.conn.callJson(ses.aren, "Page.setInterceptFileChooserDialog", "{\"enabled\":false}", CF.calz) catch {}; var from = ses.conn.evts.items.len; const btn = try ses.findKey("atta_butt"); try ses.clickNode(btn); const evt = (try ses.conn.evWait(ses.aren, "Page.fileChooserOpened", &from, CF.evwt)) orelse return error.Fail; const val = std.json.parseFromSliceLeaky(std.json.Value, ses.aren, evt, .{}) catch return error.Fail; if (val != .object) return error.Fail; const par = val.object.get("params") orelse return error.Fail; if (par != .object) return error.Fail; const bid = par.object.get("backendNodeId") orelse return error.Fail; if (bid != .integer) return error.Fail; const quo = try std.json.Stringify.valueAlloc(ses.aren, abs, .{}); const body = try std.fmt.allocPrint(ses.aren, "{{\"files\":[{s}],\"backendNodeId\":{d}}}", .{ quo, bid.integer }); _ = try ses.conn.callJson(ses.aren, "DOM.setFileInputFiles", body, CF.calz); }
fn uploaded(ses: *sess.Sess, name: []const u8) !bool { if (ses.reg.ext.msg_sel.len > 0) { const ms = try extr.msgsDom(ses.aren, ses.conn, ses.reg.ext); var idx = ms.len; while (idx > 0) { idx -= 1; const m = ms[idx]; if (std.mem.eql(u8, m.dir, "me") and std.mem.find(u8, m.text, name) != null) { const busy = fnd.markPos(&ses.reg, m.text, "upld_busy"); return busy == null; } } return false; } const lst = try ses.nodes(); const all = try fnd.allKey(ses.aren, &ses.reg, lst, "mesg_item"); var idx = all.len; while (idx > 0) { idx -= 1; if (std.mem.find(u8, all[idx].name, name) != null) return fnd.markPos(&ses.reg, all[idx].name, "upld_busy") == null; } return false; }
fn inChat(ses: *sess.Sess, name: []const u8) !bool { if (ses.reg.ext.msg_sel.len > 0) { const ms = try extr.msgsDom(ses.aren, ses.conn, ses.reg.ext); for (ms) |m| { if (std.mem.eql(u8, m.dir, "me") and std.mem.find(u8, m.text, name) != null) return true; } return false; } const lst = try ses.nodes(); const all = try fnd.allKey(ses.aren, &ses.reg, lst, "mesg_item"); for (all) |nod| { if (std.mem.find(u8, nod.name, name) != null) return true; } return false; }
fn waitUp(ses: *sess.Sess, name: []const u8) !bool { var cnt: u32 = 0; while (cnt < ses.cfg.retr_coun_maxz + 3) : (cnt += 1) { if (try uploaded(ses, name)) return true; std.Io.sleep(ses.iozz, .fromMilliseconds(if (ses.fast) 120 else 1000), .awake) catch {}; } return false; }
pub fn sendFile(ses: *sess.Sess, chat: []const u8, raw: []const u8) !Out { if (ses.mode == .read) return error.BadUsage; const chk = try check(ses.aren, ses.iozz, ses.cfg.outb_dirz_path, raw, ses.cfg.file_size_maxz); if (ses.mode == .dry) { try ses.pre(.read); const note = try std.fmt.allocPrint(ses.aren, "PREVIEW file {s}: {s} ({d} bytes)", .{ chat, chk.name, chk.size }); ses.logz("info", note); return .dry; }
try ses.pre(.upld); const opened = try opn.openChat(ses, chat); const key = try std.fmt.allocPrint(ses.aren, "file:{s}", .{chk.hash[0..24]}); const beg = try ses.sto.sendBegin(opened.name, key, ses.now()); if (beg == .dup) { ses.logz("info", "duplicate file skipped"); return .dup; } if (beg == .pend and try inChat(ses, chk.name)) { if (!try waitUp(ses, chk.name)) return error.Fail; try ses.sto.sendDone(opened.name, key, ses.now()); try ses.sto.actAdd(ses.now(), "upld"); ses.logz("info", "resumed: file already in chat"); return .sent; }
try chooseFiles(ses, chk.path); ses.fire("after_choose"); if (!try waitUp(ses, chk.name)) { ses.logz("error", "upload not confirmed"); return error.Fail; } try ses.sto.sendDone(opened.name, key, ses.now()); try ses.sto.actAdd(ses.now(), "upld"); const note = try std.fmt.allocPrint(ses.aren, "file sent to {s}: {d} bytes", .{ opened.name, chk.size }); ses.logz("info", note); _ = priv.bodyLog; ses.pause(); return .sent; }
